// Folklore Map: shows the YASHPEH folktales on a map, grouped by tradition.
// Data is generated by scripts/build-map-data.js into data/map.json.

(async function () {
  const $ = (sel) => document.querySelector(sel);
  const listEl = $('#list');
  const searchEl = $('#search');
  const bookEl = $('#book');

  const data = await fetch('data/map.json').then((r) => r.json());
  const places = data.places.map((p) => ({
    ...p,
    stories: p.stories.map(([id, title, bookId, tradition, excerpt]) => ({
      id,
      title: title || 'Untitled',
      bookId,
      tradition,
      excerpt,
      search: `${title} ${excerpt}`.toLowerCase(),
    })),
  }));
  const placeById = new Map(places.map((p) => [p.id, p]));
  const totalStories = places.reduce((n, p) => n + p.stories.length, 0);

  $('#summary').textContent = `${totalStories.toLocaleString()} tales from ${Object.keys(data.books).length} books, ${places.length} places`;

  for (const [id, book] of Object.entries(data.books).sort((a, b) => a[1].name.localeCompare(b[1].name))) {
    bookEl.add(new Option(`${book.name} (${book.author})`, id));
  }

  const map = L.map('map', { worldCopyJump: true, minZoom: 2 }).setView([35, 20], 2);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    maxZoom: 12,
  }).addTo(map);

  let selectedId = null;
  let filtered = new Map(); // place id -> matching stories

  const radius = (n) => 3 + Math.sqrt(n);

  const markers = new Map(
    places.map((p) => {
      const marker = L.circleMarker([p.lat, p.lng], {
        color: '#fff',
        weight: 1.5,
        fillOpacity: 0.8,
      });
      marker.on('click', () => select(p.id, false));
      return [p.id, marker];
    }),
  );

  function applyFilter() {
    const q = searchEl.value.trim().toLowerCase();
    const book = bookEl.value ? Number(bookEl.value) : null;
    filtered = new Map();
    for (const p of places) {
      const matches = p.stories.filter((s) => (!book || s.bookId === book) && (!q || s.search.includes(q)));
      filtered.set(p.id, matches);
      const marker = markers.get(p.id);
      if (matches.length) {
        marker.setRadius(radius(matches.length));
        marker.setStyle({ fillColor: p.id === selectedId ? '#7a2a17' : '#c4532f', weight: p.id === selectedId ? 3 : 1.5 });
        const label = `${p.name} · ${matches.length} ${matches.length === 1 ? 'tale' : 'tales'}`;
        if (marker.getTooltip()) marker.setTooltipContent(label);
        else marker.bindTooltip(label);
        marker.addTo(map);
      } else {
        marker.remove();
      }
    }
    render();
  }

  function select(id, pan = true) {
    selectedId = id;
    const p = placeById.get(id);
    if (p && pan) map.flyTo([p.lat, p.lng], Math.max(map.getZoom(), 4), { duration: 0.6 });
    history.replaceState(null, '', id ? `#${id}` : location.pathname + location.search);
    applyFilter();
    listEl.scrollTop = 0;
  }

  function el(tag, attrs = {}, ...children) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v);
    }
    node.append(...children.filter((c) => c != null));
    return node;
  }

  function render() {
    listEl.replaceChildren();
    const place = selectedId && placeById.get(selectedId);

    if (place) {
      const stories = filtered.get(place.id) ?? [];
      listEl.append(
        el('div', { class: 'list-head' }, el('h2', {}, place.name), el('button', { class: 'link', onclick: () => select(null, false) }, '← All places')),
      );
      if (!stories.length) {
        listEl.append(el('p', { class: 'empty' }, 'No tales here match the current filter.'));
        return;
      }
      const ul = el('ul');
      for (const s of stories) {
        const book = data.books[s.bookId];
        ul.append(
          el(
            'li',
            { class: 'story' },
            el(
              'details',
              {},
              el('summary', {}, el('div', { class: 'title' }, s.title), el('div', { class: 'meta' }, `${book.name} · ${s.tradition ?? 'Unknown tradition'}`)),
              s.excerpt ? el('p', {}, s.excerpt) : null,
              el('a', { href: data.storyUrl + s.id, target: '_blank', rel: 'noopener' }, 'Read the full tale ↗'),
            ),
          ),
        );
      }
      listEl.append(ul);
      return;
    }

    const visible = places.map((p) => [p, filtered.get(p.id).length]).filter(([, n]) => n).sort((a, b) => b[1] - a[1]);
    const shown = visible.reduce((n, [, c]) => n + c, 0);
    listEl.append(el('div', { class: 'list-head' }, el('span', {}, `${visible.length} places`), el('span', {}, `${shown.toLocaleString()} tales`)));
    if (!visible.length) {
      listEl.append(el('p', { class: 'empty' }, 'No tales match the current filter.'));
      return;
    }
    const ul = el('ul');
    for (const [p, n] of visible) {
      ul.append(
        el(
          'li',
          {
            class: 'place',
            tabindex: '0',
            onclick: () => select(p.id),
            onkeydown: (e) => e.key === 'Enter' && select(p.id),
            onmouseenter: () => markers.get(p.id).openTooltip(),
            onmouseleave: () => markers.get(p.id).closeTooltip(),
          },
          el('span', {}, p.name),
          el('span', { class: 'count' }, n.toLocaleString()),
        ),
      );
    }
    listEl.append(ul);
  }

  let debounce;
  searchEl.addEventListener('input', () => {
    clearTimeout(debounce);
    debounce = setTimeout(applyFilter, 150);
  });
  bookEl.addEventListener('change', () => {
    // Zoom to the selected book's places.
    applyFilter();
    const hits = places.filter((p) => filtered.get(p.id).length);
    if (bookEl.value && hits.length) map.flyToBounds(L.latLngBounds(hits.map((p) => [p.lat, p.lng])).pad(0.5), { maxZoom: 5, duration: 0.6 });
  });

  const initial = decodeURIComponent(location.hash.slice(1));
  select(placeById.has(initial) ? initial : null, placeById.has(initial));
})();
